SELECT 'rp-2026-10-17-cr1-' || p.id || '-' || f.f, 'wip_packages', p.id, f.f, NULL, CASE f.f WHEN 'id' THEN CAST(p.id AS TEXT) WHEN 'wet_weight_entry_id' THEN CAST(p.wet_weight_entry_id AS TEXT) WHEN 'harvest_batch_id' THEN CAST(p.harvest_batch_id AS TEXT) WHEN 'package_code' THEN CAST(p.package_code AS TEXT) WHEN 'package_type_code' THEN CAST(p.package_type_code AS TEXT) WHEN 'weight_grams' THEN CAST(p.weight_grams AS TEXT) WHEN 'cryo_weight_grams' THEN CAST(p.cryo_weight_grams AS TEXT) WHEN 'status' THEN CAST(p.status AS TEXT) WHEN 'cryo_date' THEN CAST(p.cryo_date AS TEXT) WHEN 'cryo_operator' THEN CAST(p.cryo_operator AS TEXT) WHEN 'cryo_run_id' THEN CAST(p.cryo_run_id AS TEXT) WHEN 'source' THEN CAST(p.source AS TEXT) WHEN 'created_at' THEN CAST(p.created_at AS TEXT) WHEN 'created_by' THEN CAST(p.created_by AS TEXT) WHEN 'updated_at' THEN CAST(p.updated_at AS TEXT) WHEN 'updated_by' THEN CAST(p.updated_by AS TEXT) END, '7b59cf6b-04b6-4742-bb1b-78a28b593fe8', 'repair 2026-10-17 (canon 0.30.512): CR1, cryo entries matched to the floor sheet', p.created_at
